import { setActiveTheme as setPackageActiveTheme, type SetActiveThemeRequired as PackageRequired, type PresentationOptional } from "@jini-ai/cms/presentation";
import type { Tracker } from "@jini-ai/diagnostics/observability";

/** CMS telemetry adapter around the shared theme write owner; no theme discovery or policy lives here. */
export interface SetActiveThemeRequired extends Omit<PackageRequired, "deps"> {
  deps: PackageRequired["deps"] & { tracker?: Tracker };
}

/** Capture a successful actual active-theme change, including assistant callers. Same-value retries
 * retain the shared service response and emit nothing. @complexity O(1), one indexed pre-read. */
export async function setActiveTheme(
  required: SetActiveThemeRequired,
  optional: PresentationOptional & { actorId?: string; source?: "admin" | "assistant" | "service"; capture?: boolean } = {},
) {
  const previous = await required.deps.repo.findByWorkspaceId({ workspaceId: required.input.workspaceId });
  const result = await setPackageActiveTheme(required, optional);
  if (previous?.activeThemeId !== result.settings.activeThemeId && optional.capture !== false) {
    try { required.deps.tracker?.capture({ name: "theme_changed", userId: optional.actorId ?? `system:${required.input.workspaceId}` }, { properties: {
      themeId: result.settings.activeThemeId, source: optional.source ?? "service",
    } }); } catch { /* Analytics cannot undo the committed theme choice. */ }
  }
  return result;
}

import type { UUID } from "@jini-ai/core/primitives";
import { ensureSettingDefinitions, getEffective, SCOPE_BIT, type EnsureSettingDefinitionsDeps, type SettingsRepoPort } from "@jini-ai/core/settings";
import { DEFAULT_SITE_TIME_ZONE, normalizeTimeZone, type SiteTimeZonePort } from "@jini-ai/cms/widgets/date-label";

/**
 * @file Bug D (2026-10-22): `core.site.timezone`, the IANA zone public pages format post dates in.
 * Dates rendered server-side in UTC showed the day after a post's real date for any site west of UTC
 * that published in the evening (and the day before for one east of it publishing early). Static
 * pages carry no JavaScript to correct that, so the zone is a site setting the render reads.
 *
 * Tiers, in order (same "only a workspace-layer value is the owner's choice" rule as
 * `core.site.title`): the owner's workspace value; the zone detected when the site was created
 * (`config.json` `timezone`, written by `init-site.ts`); the server's local zone. An invalid value at
 * any tier falls to the next. A WordPress import sets the owner value from the source site's `timezone_string`
 * through `settings_set_value` (see the `site-import` skill). Stored post instants never shift.
 *
 * `ownerKind: "core"` and the platform-wide definition are forced by the settings namespace fence for
 * `core.*`, exactly as for `core.site.title`; values stay per-workspace through `SCOPE_BIT.workspace`.
 */

export const SITE_TIMEZONE_NAMESPACE = "core.site";
export const SITE_TIMEZONE_KEY = "timezone";

/**
 * Idempotently registers `core.site.timezone` (default UTC). Safe on every boot.
 * @complexity O(1), one definition.
 */
export async function ensureSiteTimeZoneSettingDefinition(
  deps: EnsureSettingDefinitionsDeps,
  input: { systemPrincipalId: UUID }
): Promise<void> {
  await ensureSettingDefinitions(deps, {
    namespace: SITE_TIMEZONE_NAMESPACE,
    definitions: [{ key: SITE_TIMEZONE_KEY, schema: { type: "string" }, defaultValue: DEFAULT_SITE_TIME_ZONE, scopes: SCOPE_BIT.workspace }],
    systemPrincipalId: input.systemPrincipalId,
  });
}

/** The zone detected where the site was created, read when a render needs it. Should not throw. */
export interface SiteCreationTimeZoneSource {
  read(): string | undefined;
}

export interface ResolveSiteTimeZoneDeps {
  settingsRepo: SettingsRepoPort;
  /** Absent (in-memory boots, no site directory) means the server's local zone is the last tier. */
  creationTimeZone?: SiteCreationTimeZoneSource;
}

/** `value` trimmed when `Intl` accepts it (an explicit "UTC" included), else undefined. */
function validTimeZone(value: unknown): string | undefined {
  if (typeof value !== "string") return undefined;
  const zone = normalizeTimeZone({ timeZone: value });
  // `normalizeTimeZone` returns the trimmed input only for a valid zone; anything else became UTC.
  return zone === value.trim() ? zone : undefined;
}

/** The creation zone when valid, else the server's local zone. */
function creationOrDefault(deps: ResolveSiteTimeZoneDeps): string {
  // Legacy sites have no recorded zone. Pin the server's local zone before shared rendering so
  // article markers, Liquid workers and static exports all use the same calendar day.
  return validTimeZone(deps.creationTimeZone?.read()) ?? Intl.DateTimeFormat().resolvedOptions().timeZone;
}

/** A usable owner value: a workspace-layer string `Intl` accepts. */
function ownerTimeZone(resolved: { sourceLayer: string; value: unknown } | null): string | undefined {
  return resolved?.sourceLayer === "workspace" ? validTimeZone(resolved.value) : undefined;
}

/**
 * The zone a public render formats `workspaceId`'s dates in. Reads without a principal, so the user
 * layer never applies. Never throws: a failed settings read logs and uses the creation zone.
 * @complexity One settings read.
 */
export async function resolveSiteTimeZone(deps: ResolveSiteTimeZoneDeps, input: { workspaceId: UUID }): Promise<string> {
  try {
    const resolved = await getEffective(
      { repo: deps.settingsRepo },
      { namespace: SITE_TIMEZONE_NAMESPACE, key: SITE_TIMEZONE_KEY, scopeContext: { workspaceId: input.workspaceId } }
    );
    return ownerTimeZone(resolved) ?? creationOrDefault(deps);
  } catch (err) {
    // eslint-disable-next-line no-console
    console.error(`resolveSiteTimeZone: using the creation zone for workspace '${input.workspaceId}': ${(err as Error).message}`);
    return creationOrDefault(deps);
  }
}

/** {@link resolveSiteTimeZone} as the `SiteTimeZonePort` the Jini render resolvers take. */
export function createSiteTimeZonePort(deps: ResolveSiteTimeZoneDeps): SiteTimeZonePort {
  return { resolveTimeZone: (required) => resolveSiteTimeZone(deps, required) };
}

import { nowIso as clockNowIso } from "@jini-ai/core/primitives";
import type { JsonValue, UUID } from "@jini-ai/core/primitives";
// From the package, not `./index.js`: the barrel's `set` comes from `site-title-write.ts`, which
// imports this file.
import {
  ensureSettingDefinitions,
  type EnsureSettingDefinitionsDeps,
  getEffective,
  resolveDefinitionRaw,
  SCOPE_BIT,
  set,
  type AuthorizeFn,
  type SettingsRepoPort,
} from "@jini-ai/core/settings";
import type { WorkspaceRecord } from "@jini-ai/cms/workspace";

/**
 * @file SPEC-050 (`core.site.title`): the public site title as a per-workspace setting, the one
 * resolver every render call site reads it through (REQ-02), and the one-time pin that keeps every
 * site that existed before this setting on the title it always rendered (REQ-06).
 *
 * The "no owner-set title" value has two tiers (NC-1 = A):
 * - A workspace the marker migration recorded as pre-existing (NC-3 = A) is pinned to
 *   {@link LEGACY_SITE_TITLE} at the workspace layer, through the settings chokepoint. Until that pin
 *   lands the workspace is pending, and renders the legacy title anyway (REQ-07).
 * - Every other workspace renders the site display name: `config.json` `name`, else
 *   `workspaces.name` when there is no site directory (NC-2 = B).
 *
 * Only a workspace-layer value counts as a title. The definition default stays the legacy literal,
 * and a default-layer read means "no owner-set title".
 *
 * `ownerKind: "core"` is forced, not chosen. The settings namespace fence (`@jini-ai/core/settings`
 * `NAMESPACE_FENCE`) admits a `core.*` namespace only for a core definition, and requires such a
 * definition to be platform-wide (`workspaceId: null`). Its VALUES stay per-workspace through
 * `scopes: SCOPE_BIT.workspace`, which is REQ-01's shape.
 */

export const SITE_TITLE_NAMESPACE = "core.site";
export const SITE_TITLE_KEY = "title";

/** The title every site rendered before this setting existed (formerly `pages.ts`'s `SITE_TITLE`). */
export const LEGACY_SITE_TITLE = "Tovu Demo Site";

/** REQ-08's upper bound, mirroring `init-site.ts`'s limit for site display names. */
export const SITE_TITLE_MAX_LENGTH = 200;

export interface EnsureSiteTitleSettingDefinitionInput {
  /** The trusted boot-time actor the registration is attributed to (same convention as every other boot registrar). */
  systemPrincipalId: UUID;
}

/**
 * Idempotently registers the `core.site.title` definition. Safe to call on every boot:
 * `ensureSettingDefinitions` skips a registered definition and reconciles a changed core default.
 *
 * @complexity O(1), one definition.
 */
export async function ensureSiteTitleSettingDefinition(
  deps: EnsureSettingDefinitionsDeps,
  input: EnsureSiteTitleSettingDefinitionInput
): Promise<void> {
  await ensureSettingDefinitions(deps, {
    namespace: SITE_TITLE_NAMESPACE,
    definitions: [
      { key: SITE_TITLE_KEY, schema: { type: "string" }, defaultValue: LEGACY_SITE_TITLE, scopes: SCOPE_BIT.workspace },
    ],
    systemPrincipalId: input.systemPrincipalId,
  });
}

/**
 * The renderable form of a stored title or name: trimmed, 1..{@link SITE_TITLE_MAX_LENGTH}
 * characters. Anything else is `undefined`, so a caller falls back instead of rendering an empty or
 * unbounded `<title>` (REQ-08, REQ-09, INV-04). Pure.
 *
 * @complexity O(n) in the value's length.
 */
export function normalizeSiteTitle(value: JsonValue | undefined): string | undefined {
  if (typeof value !== "string") return undefined;
  const trimmed = value.trim();
  return trimmed.length > 0 && trimmed.length <= SITE_TITLE_MAX_LENGTH ? trimmed : undefined;
}

/**
 * The pre-existing-workspace marker (REQ-06, NC-3 = A). A workspace is recorded once, by the schema
 * migration, and stays pending until the pin writes or skips it. The SQLite adapter reads the
 * migration's table; the in-memory composition root has no pre-existing workspaces (EC-03).
 */
export interface SiteTitlePreservationStorePort {
  /** Recorded workspaces whose pin has not landed yet, sorted by id. */
  listPendingWorkspaceIds(): Promise<UUID[]>;
  /** True only for a recorded workspace whose pin has not landed yet. */
  isPending(workspaceId: UUID): Promise<boolean>;
  /** Resolves one pending workspace. A no-op for an unrecorded or already resolved id. */
  markPreserved(required: { workspaceId: UUID; preservedAt: string }): Promise<void>;
}

/** {@link SiteTitlePreservationStorePort} over a process-local set. */
export class InMemorySiteTitlePreservationStore implements SiteTitlePreservationStorePort {
  private readonly pending: Set<UUID>;

  constructor(pendingWorkspaceIds: readonly UUID[] = []) {
    this.pending = new Set(pendingWorkspaceIds);
  }

  async listPendingWorkspaceIds(): Promise<UUID[]> {
    return [...this.pending].sort();
  }

  async isPending(workspaceId: UUID): Promise<boolean> {
    return this.pending.has(workspaceId);
  }

  async markPreserved(required: { workspaceId: UUID; preservedAt: string }): Promise<void> {
    this.pending.delete(required.workspaceId);
  }
}

export interface PreserveLegacySiteTitlesDeps extends EnsureSettingDefinitionsDeps {
  preservationStore: SiteTitlePreservationStorePort;
}

/** REQ-11's report: every pending workspace lands in exactly one list. */
export interface PreserveLegacySiteTitlesResult {
  pinnedWorkspaceIds: UUID[];
  skippedWorkspaceIds: UUID[];
  failedWorkspaceIds: UUID[];
}

/** Always-allow shim scoped to this one system write, the same shape `migration.ts` uses for its own. */
const allowSystemPin: AuthorizeFn = async () => ({ allowed: true, reason: "system_migration" });

type PinOutcome = "pinned" | "skipped" | "failed";

/**
 * REQ-06/REQ-11: pins every pending pre-existing workspace to {@link LEGACY_SITE_TITLE} with one
 * workspace-layer `set`, attributed to `systemPrincipalId`.
 *
 * - Skips a workspace that already has a workspace-layer row in any state (`set` or `cleared`), so an
 *   explicit owner action always wins (INV-02).
 * - Resolves the marker only AFTER the write. A crash between the two leaves a value row, which the
 *   next run skips, never a second pin.
 * - Logs a failed workspace and leaves it pending for the next boot. It never aborts the others or boot.
 *
 * Safe on every boot: with nothing pending it costs one marker read.
 *
 * @complexity O(p) sequential ledger writes for p pending workspaces, once per database.
 */
export async function preserveLegacySiteTitles(
  deps: PreserveLegacySiteTitlesDeps,
  input: { systemPrincipalId: UUID }
): Promise<PreserveLegacySiteTitlesResult> {
  const result: PreserveLegacySiteTitlesResult = { pinnedWorkspaceIds: [], skippedWorkspaceIds: [], failedWorkspaceIds: [] };
  const pendingWorkspaceIds = await deps.preservationStore.listPendingWorkspaceIds();
  if (pendingWorkspaceIds.length === 0) return result;

  const definition = await resolveDefinitionRaw(
    { repo: deps.settingsRepo },
    { namespace: SITE_TITLE_NAMESPACE, key: SITE_TITLE_KEY, workspaceId: null }
  );
  for (const workspaceId of pendingWorkspaceIds) {
    const outcome: PinOutcome = definition
      ? await pinOneWorkspace(deps, { settingId: definition.settingId, workspaceId, systemPrincipalId: input.systemPrincipalId })
      : logPinFailure(workspaceId, "core.site/title is not registered");
    if (outcome === "pinned") result.pinnedWorkspaceIds.push(workspaceId);
    else if (outcome === "skipped") result.skippedWorkspaceIds.push(workspaceId);
    else result.failedWorkspaceIds.push(workspaceId);
  }

  // eslint-disable-next-line no-console
  console.info(
    `preserveLegacySiteTitles: pinned=${result.pinnedWorkspaceIds.length} skipped=${result.skippedWorkspaceIds.length} failed=${result.failedWorkspaceIds.length}`
  );
  return result;
}

/** One workspace of {@link preserveLegacySiteTitles}. Catch-log-continue is this function's contract. */
async function pinOneWorkspace(
  deps: PreserveLegacySiteTitlesDeps,
  required: { settingId: UUID; workspaceId: UUID; systemPrincipalId: UUID }
): Promise<PinOutcome> {
  const { workspaceId } = required;
  try {
    const existing = await deps.settingsRepo.getWorkspaceValue({ workspaceId, settingId: required.settingId });
    if (!existing) {
      await set({
        deps: { repo: deps.settingsRepo, clock: deps.clock, ids: deps.ids, authorize: allowSystemPin, principals: deps.principals },
        input: {
          namespace: SITE_TITLE_NAMESPACE,
          key: SITE_TITLE_KEY,
          scope: "workspace",
          workspaceId,
          authWorkspaceId: workspaceId,
          value: LEGACY_SITE_TITLE,
          callerPrincipalId: required.systemPrincipalId,
        },
      });
    }
    await deps.preservationStore.markPreserved({ workspaceId, preservedAt: clockNowIso({ clock: deps.clock }) });
    return existing ? "skipped" : "pinned";
  } catch (err) {
    return logPinFailure(workspaceId, (err as Error).message);
  }
}

function logPinFailure(workspaceId: UUID, reason: string): "failed" {
  // eslint-disable-next-line no-console
  console.error(`preserveLegacySiteTitles: workspace '${workspaceId}' stays pending, pin failed: ${reason}`);
  return "failed";
}

/**
 * REQ-13: the served site's display name, read when a render needs it rather than captured once at
 * boot, so a `config.json` rename shows on the next render with no restart.
 */
export interface SiteDisplayNameSource {
  /**
   * The display name as it stands now, or `undefined` when there is none. The resolver normalizes it.
   * Should not throw; a throw renders {@link LEGACY_SITE_TITLE} (REQ-09).
   */
  read(): string | undefined;
}

export interface ResolveSiteTitleDeps {
  settingsRepo: SettingsRepoPort;
  preservationStore: Pick<SiteTitlePreservationStorePort, "isPending">;
  workspaceRepo: { findById(required: { id: UUID }): Promise<WorkspaceRecord | null> };
  /**
   * `config.json` `name` of the site directory this process serves (NC-2 = B), read at each
   * resolution that reaches it (REQ-13). A config rename and a `workspaces.name` rename both show on
   * the next render (OQ-01, EC-01). Reads `undefined` when there is no site directory.
   */
  siteDisplayName: SiteDisplayNameSource;
}

/**
 * The site title a public render shows for `workspaceId` (REQ-03). Reads without a principal, so the
 * user layer never applies (INV-03). In order:
 * 1. a usable workspace-layer value (an owner title, or the pin);
 * 2. {@link LEGACY_SITE_TITLE} while the workspace's pin is pending, or while the definition is not
 *    registered yet (REQ-07);
 * 3. the site display name, else `workspaces.name` (REQ-05);
 * 4. {@link LEGACY_SITE_TITLE}.
 *
 * Never throws. Any failed read renders {@link LEGACY_SITE_TITLE} rather than guess the tier, because
 * a pinned site that loses its settings read must not flip (REQ-09, INV-01).
 *
 * @complexity O(1) repo reads per call, at most one of them a workspace lookup, plus one bounded
 * display-name read on step 3 only (REQ-13).
 */
export async function resolveSiteTitle(deps: ResolveSiteTitleDeps, input: { workspaceId: UUID }): Promise<string> {
  try {
    // The marker is read BEFORE the value. The pin writes the value first and resolves the marker
    // second, so a pending marker can only be followed by no value or the pin, and both render the
    // legacy title. In the other order, a pin landing between the two reads would render the
    // display name for that request.
    const pending = await deps.preservationStore.isPending(input.workspaceId);
    const resolved = await getEffective(
      { repo: deps.settingsRepo },
      { namespace: SITE_TITLE_NAMESPACE, key: SITE_TITLE_KEY, scopeContext: { workspaceId: input.workspaceId } }
    );
    if (resolved === null) return LEGACY_SITE_TITLE;
    const workspaceTitle = resolved.sourceLayer === "workspace" ? normalizeSiteTitle(resolved.value) : undefined;
    if (workspaceTitle !== undefined) return workspaceTitle;
    if (pending) return LEGACY_SITE_TITLE;
    return (await resolveSiteDisplayName(deps, input.workspaceId)) ?? LEGACY_SITE_TITLE;
  } catch (err) {
    // eslint-disable-next-line no-console
    console.error(`resolveSiteTitle: falling back to the legacy title for workspace '${input.workspaceId}': ${(err as Error).message}`);
    return LEGACY_SITE_TITLE;
  }
}

/** NC-2 = B: the configured display name as it stands now (REQ-13), else the workspace row's name, each only if renderable. */
async function resolveSiteDisplayName(deps: ResolveSiteTitleDeps, workspaceId: UUID): Promise<string | undefined> {
  const configured = normalizeSiteTitle(deps.siteDisplayName.read());
  if (configured !== undefined) return configured;
  const workspace = await deps.workspaceRepo.findById({ id: workspaceId });
  return normalizeSiteTitle(workspace?.name);
}

import { tidyImportDatabases } from "./import-database.js";
import type { Tracker } from "@jini-ai/diagnostics/observability";
import fs from "node:fs";
import path from "node:path";
import { randomUUID } from "node:crypto";
import type { AgentPluginArchiveReaderPort } from "@jini-ai/agent-plugins/lifecycle";
import type { HttpClientPort } from "#src/platform/http/index";
import type { CreateSitePort, CreateSiteResult } from "#src/platform/site-dir/index";
import { resolveNewSiteAdminPassword } from "#src/platform/site-dir/index";
import type { SitesWorkspace } from "#src/platform/site-dir/index";
import { importSourceDigest, withoutQuery, type SiteImportRegistry, type SiteImportRecord } from "./import-registry.js";
import { SHARE_LIMITS, SiteShareRefusal, type ShareDatabaseSanitizer } from "./share-policy.js";
import { verifySiteImport } from "./import-verifier.js";
import { stageVerifiedImport, stagedImportWarnings } from "./import-restore.js";
import {
  consumeUpload, deadlineSignal, downloadShareArchive, importSiteSlug, parseImportInput, reconcileInterruptedImports, refusal,
  requireFreeSpace, requireOwnerSetup, requireStagingBudget, siteImportView, startImportedSite,
  type ParsedSiteImportInput, type SiteImportSource, type SiteImportView,
} from "./import-backend-steps.js";

export type { SiteImportSource, SiteImportView } from "./import-backend-steps.js";
export interface SiteImportBackend {
  upload(required: { principalId: string; archive: Buffer }, optional?: Record<string, never>): Promise<{ uploadId: string }>;
  importBackup(required: { principalId: string; source: SiteImportSource; displayName?: string; requestId?: string }, optional?: { signal?: AbortSignal }): Promise<SiteImportView>;
  completeOwner(required: { principalId: string; importId: string; adminPassword: unknown; savedKeysPassword?: unknown }, optional?: { signal?: AbortSignal }): Promise<SiteImportView>;
  list(required: { principalId: string }, optional?: Record<string, never>): Promise<SiteImportView[]>;
  get(required: { principalId: string; importId: string }, optional?: Record<string, never>): SiteImportView;
  /** Settles interrupted imports and removes expired or orphaned payloads, with no import to start. */
  tidy(required: Record<string, never>, optional?: Record<string, never>): Promise<void>;
}


/** Source union is enforced at every remote boundary; server paths are never accepted. */
export function parseSiteImportInput(required: { input: unknown }, _options: Record<string, never> = {}): ParsedSiteImportInput {
  return parseImportInput(required);
}

/** Shared HTTP/tool application service. All effects enter as ports; CMS policy stays here.
 * Pending owner setup stores sanitized bytes privately without creating any site directory.
 * @complexity O(archive bytes + registry history), with one buffered job and four staged payloads.
 */
export function createSiteImportBackend(required: {
  registry: SiteImportRegistry; workspace: SitesWorkspace; reader: AgentPluginArchiveReaderPort; http: HttpClientPort;
  sanitize: ShareDatabaseSanitizer; schema: { index: number; tag: string };
  startSite: (required: { name: string }) => Promise<{ adminUrl: string | null; status: string }>;
  tracker?: Tracker;
  createSite: CreateSitePort;
  restoreStagedImport: (required: { root: string; dir: string; dbPath: string; siteId: string }, optional?: { pluginSourceRoot?: string; savedKeysPassword?: string; signal?: AbortSignal }) => Promise<void>;
  setupBase?: string;
  creationOptions?: Parameters<CreateSitePort>[1];
}, optional: {
  createSite?: CreateSitePort;
  report?: (required: { importId: string; status: string }) => void;
} = {}): SiteImportBackend {
  const { registry, workspace } = required;
  const view = (row: SiteImportRecord): SiteImportView => {
    const warnings = stagedImportWarnings({ root: registry.stagePath(row) });
    return { ...siteImportView({ row }, { setupBase: required.setupBase }), ...(warnings.length ? { warnings } : {}) };
  };
  const put = (row: SiteImportRecord) => { registry.put({ row }); optional.report?.({ importId: row.importId, status: row.status }); };
  let active = false;
  const exclusive = async <T>(run: () => Promise<T>): Promise<T> => {
    if (active) refusal("BUSY", "Another import is running. Retry after it finishes.");
    active = true;
    try { return await registry.exclusive({ run: async () => { await reconcileInterruptedImports({ registry, workspace, put }); return run(); } }); } finally { active = false; }
  };

  /** Reads or downloads the archive; records the consumed upload before reading so it is always removed. */
  const fetchArchive = async (input: { parsed: ParsedSiteImportInput; principalId: string; importId: string; signal: AbortSignal; consumed: (uploadId: string) => void }): Promise<Buffer> => {
    const { source } = input.parsed;
    if ("url" in source) { input.signal.throwIfAborted(); return downloadShareArchive({ http: required.http, url: source.url, signal: input.signal }); }
    const uploadId = consumeUpload({ registry, uploadId: source.uploadId, principalId: input.principalId, importId: input.importId });
    input.consumed(uploadId);
    input.signal.throwIfAborted();
    return fs.readFileSync(registry.uploadPath({ uploadId }));
  };

  /** Verify, stage and mark the row pending owner setup; any failure removes the stage and records why. */
  const verifyAndStage = async (input: { row: SiteImportRecord; parsed: ParsedSiteImportInput; signal: AbortSignal }): Promise<SiteImportView> => {
    let consumedUpload: string | undefined;
    let row = input.row;
    try {
      const archive = await fetchArchive({ parsed: input.parsed, principalId: input.row.principalId, importId: input.row.importId, signal: input.signal, consumed: uploadId => { consumedUpload = uploadId; } });
      const verified = await verifySiteImport({ archive, reader: required.reader, sanitize: required.sanitize, schema: required.schema }, { signal: input.signal });
      input.signal.throwIfAborted();
      stageVerifiedImport({ root: registry.stagePath(input.row), verified });
      row = { ...row, displayName: input.parsed.displayName ?? verified.name, status: "needs-owner", hasEncryptedKeys: Boolean(verified.encryptedKeys), credentialWarnings: verified.credentialWarnings ?? [], warnings: stagedImportWarnings({ root: registry.stagePath(row) }) };
      put(row);
      return view(row);
    } catch (error) {
      fs.rmSync(registry.stagePath(row), { recursive: true, force: true });
      put({ ...row, status: "failed", error: error instanceof SiteShareRefusal ? error.message : "Archive verification failed. No site was created." });
      throw error;
    } finally { if (consumedUpload) fs.rmSync(registry.uploadPath({ uploadId: consumedUpload }), { force: true }); }
  };

  /** Creates the site from the stage; a failure rolls the row back to failed and removes the stage. */
  const createImportedSite = async (input: { row: SiteImportRecord; adminPassword: string; savedKeysPassword?: string; signal: AbortSignal }): Promise<{ row: SiteImportRecord; created: CreateSiteResult }> => {
    const { signal } = input;
    let row = input.row;
    try {
      const created = await (optional.createSite ?? required.createSite)({ name: importSiteSlug(row), displayName: row.displayName, adminPassword: input.adminPassword }, { ...required.creationOptions, workspace, collisionSafe: true,
        onAllocated: allocation => {
          signal.throwIfAborted();
          // Persist idempotency before shared registration. A registry failure is still inside
          // createSite's compensation boundary, so a new site's identity never gets lost.
          row = { ...row, creation: allocation, newSiteId: allocation.siteId, newSiteName: allocation.name };
          put(row);
        },
        beforeRegister: () => { signal.throwIfAborted(); },
        verifiedRestore: { signal, restore: async ({ dir, dbPath, siteId }) => {
          signal.throwIfAborted();
          await required.restoreStagedImport({ root: registry.stagePath(row), dir, dbPath, siteId }, { savedKeysPassword: input.savedKeysPassword, signal });
          row = { ...row, warnings: stagedImportWarnings({ root: registry.stagePath(row) }) };
          put(row);
        } },
      });
      return { row, created };
    } catch (error) {
      fs.rmSync(registry.stagePath(row), { recursive: true, force: true });
      put({ ...row, newSiteId: null, newSiteName: null, status: "failed", error: "Site creation failed and was rolled back. Import the archive again." });
      throw error;
    }
  };

  const backend: SiteImportBackend = {
    async upload(input) {
      return exclusive(async () => {
        requireStagingBudget({ registry });
        if (!Buffer.isBuffer(input.archive) || input.archive.length > SHARE_LIMITS.maxArchiveBytes) refusal("LIMIT_EXCEEDED", "Upload exceeds the 300 MiB ZIP cap.");
        const uploadId = randomUUID();
        try {
          fs.writeFileSync(registry.uploadPath({ uploadId }), input.archive, { flag: "wx", mode: 0o600 });
          registry.saveUpload({ row: { uploadId, principalId: input.principalId, createdAt: Date.now() } });
          return { uploadId };
        } catch (error) { fs.rmSync(registry.uploadPath({ uploadId }), { force: true }); throw error; }
      });
    },
    async importBackup(input, options = {}) {
      const parsed = parseSiteImportInput({ input: { ...input.source, displayName: input.displayName, requestId: input.requestId } });
      return exclusive(async () => {
        registry.expire({});
        const existing = parsed.requestId ? registry.list(input).find(row => row.requestId === parsed.requestId) : undefined;
        if (existing) {
          const sameSource = existing.sourceDigest !== undefined
            ? existing.sourceDigest === importSourceDigest({ source: parsed.source })
            : JSON.stringify(withoutQuery({ source: existing.source })) === JSON.stringify(withoutQuery({ source: parsed.source }));
          if (!sameSource) refusal("REQUEST_CONFLICT", "requestId already belongs to another source.");
          return view(existing);
        }
        if ("url" in parsed.source) requireStagingBudget({ registry });
        const row: SiteImportRecord = { importId: randomUUID(), principalId: input.principalId, requestId: parsed.requestId, source: parsed.source, sourceDigest: importSourceDigest({ source: parsed.source }), displayName: parsed.displayName ?? "Imported site", newSiteId: null, newSiteName: null, status: "verifying", createdAt: new Date().toISOString(), expiresAt: Date.now() + 3600_000 };
        put(row);
        return verifyAndStage({ row, parsed, signal: deadlineSignal({ timeoutMs: 5 * 60_000 }, options) });
      });
    },
    async completeOwner(input, options = {}) {
      const signal = deadlineSignal({ timeoutMs: 120_000 }, options);
      return exclusive(async () => {
        registry.expire({});
        const pending = registry.get(input);
        if (pending.status === "ready") return view(pending);
        requireOwnerSetup({ row: pending, adminPassword: input.adminPassword });
        const adminPassword = resolveNewSiteAdminPassword({ adminPassword: input.adminPassword });
        if (input.savedKeysPassword !== undefined && (typeof input.savedKeysPassword !== "string" || input.savedKeysPassword.length > 1024)) refusal("INVALID_INPUT", "Saved keys password must be text of at most 1024 characters.");
        const home = workspace.home({});
        try {
          requireFreeSpace({ dir: fs.existsSync(home) ? home : path.dirname(home), message: "Import requires 900 MiB of free space on the sites-home volume." });
          signal.throwIfAborted();
        } catch (error) {
          // No site exists yet (low space, or the desktop app quitting): the verified copy must not wait out its hour.
          fs.rmSync(registry.stagePath(pending), { recursive: true, force: true });
          put({ ...pending, status: "failed", error: signal.aborted ? "The import was stopped. No site was created. Import the archive again." : "There is not enough free disk space. No site was created. Free up space and import the archive again." });
          throw error;
        }
        const creating: SiteImportRecord = { ...pending, status: "creating" }; put(creating);
        const { row: allocated, created } = await createImportedSite({ row: creating, adminPassword, savedKeysPassword: input.savedKeysPassword as string | undefined, signal });
        // Owner and restore are committed. A supervisor failure must not repeat site creation.
        const ready: SiteImportRecord = { ...allocated, newSiteId: created.siteId, newSiteName: created.name, status: "ready" };
        put(ready);
        required.tracker?.capture({ name: "site_imported", userId: ready.principalId }, { properties: { targetSiteId: created.siteId, operationId: ready.importId, eventId: `import:${ready.importId}`, source: "admin" } });
        fs.rmSync(registry.stagePath(ready), { recursive: true, force: true });
        const started = await startImportedSite({ row: ready, name: created.name, startSite: required.startSite });
        put(started);
        return view(started);
      });
    },
    async list(input) { return exclusive(async () => { registry.expire({}); return registry.list(input).map(view); }); },
    get(input) { return view(registry.get(input)); },
    async tidy() { await exclusive(async () => { registry.expire({}); await tidyImportDatabases({}); }); },
  };
  return backend;
}
